import os
import boto3

def upload_object(payload, config=None):
    config = config or {}
    s3_client = boto3.client('s3')
    bucket_name = os.environ.get('S3_BUCKET_NAME') or config.get('bucket_name', 'my-default-s3-bucket')
    object_key = config.get('object_key', 'uploaded_object.bin')

    if isinstance(payload, bytes):
        response = s3_client.put_object(Bucket=bucket_name, Key=object_key, Body=payload)
    elif isinstance(payload, str): # Assume string is a file path
        with open(payload, 'rb') as f:
            response = s3_client.put_object(Bucket=bucket_name, Key=object_key, Body=f)
    else:
        raise ValueError("Payload must be bytes or a file path string.")

    result = {
        "status": response['ResponseMetadata']['HTTPStatusCode'],
        "e_tag": response.get('ETag')
    }
    return result
